//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum delay between retries, in milliseconds.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Returns the delay for a retry numbered from zero.
    pub(crate) fn delay_for_retry(&self, retry_number: u32) -> u64 {
        let delay = self.base_delay_ms.saturating_mul(2u64.saturating_pow(retry_number));
        delay.min(self.max_delay_ms)
    }
}

mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    // A zero-attempt configuration cannot make a call, so return a permanent
    // error rather than silently violating the configured limit.
    if config.max_attempts == 0 {
        return Err(RetryError::Permanent("max_attempts must be at least 1".into()));
    }

    let mut attempts = 0;
    loop {
        attempts += 1;
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if !error.is_transient() || attempts >= config.max_attempts => {
                return Err(error)
            }
            Err(_) => {
                sleeper.sleep_ms(config.delay_for_retry(attempts - 1));
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn config(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> RetryConfig {
        RetryConfig { max_attempts, base_delay_ms, max_delay_ms }
    }

    #[test]
    fn retries_transient_errors_with_bounded_exponential_delays() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config(5, 10, 25), &mut sleeper, || {
            calls += 1;
            if calls < 5 { Err(RetryError::Transient("temporary".into())) } else { Ok(()) }
        });

        assert_eq!(result, Ok(()));
        assert_eq!(calls, 5);
        assert_eq!(sleeper.sleeps, vec![10, 20, 25, 25]);
    }

    #[test]
    fn permanent_errors_return_without_retrying() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config(4, 10, 100), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Permanent("invalid input".into()))
        });

        assert_eq!(result, Err(RetryError::Permanent("invalid input".into())));
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn max_attempts_includes_first_call() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config(3, 1, 100), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Transient("down".into()))
        });

        assert_eq!(result, Err(RetryError::Transient("down".into())));
        assert_eq!(calls, 3);
        assert_eq!(sleeper.sleeps, vec![1, 2]);
    }

    #[test]
    fn transient_classification_is_correct() {
        assert!(RetryError::Transient("x".into()).is_transient());
        assert!(!RetryError::Permanent("x".into()).is_transient());
    }
}

//! Error taxonomy for the job runner.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetryError {
    /// Transient faults may be retried (network blips, temporary locks).
    Transient(String),
    /// Permanent faults must return immediately (bad input, missing job).
    Permanent(String),
}

impl RetryError {
    /// Returns whether this error is eligible for retry.
    pub fn is_transient(&self) -> bool {
        matches!(self, Self::Transient(_))
    }
}

# jobrunner

Small job runner with a configurable, bounded exponential retry policy.

## Retry policy

`run_job` keeps its public signature and accepts a `RetryConfig`, an injected
`Sleeper`, and a job closure. `max_attempts` is the total number of calls,
including the first call. Only `RetryError::Transient` failures are retried;
`RetryError::Permanent` failures are returned immediately. Before each retry,
the runner sleeps for `base_delay_ms`, doubling the delay after each attempt
until it saturates at `max_delay_ms`.

```rust
let config = jobrunner::RetryConfig {
    max_attempts: 4,
    base_delay_ms: 100,
    max_delay_ms: 1_000,
};
let mut sleeper = jobrunner::FakeSleeper::default();
jobrunner::run_job(&config, &mut sleeper, || do_work())?;
```

`max_attempts` must be at least 1. A zero value returns a permanent
configuration error without calling the job.
